function append(id,msg,extra=[],status){const x=a.controls.find(v=>v.control_id==='A05-C'+String(id).padStart(2,'0'));x.observed+=' '+msg;if(status)x.status=status;x.evidence_ids.push(...extra.filter(v=>!x.evidence_ids.includes(v)));x.executed_at=now;return x;}
append(4,'Prin API nativ, CPP nou = 1000000 și CPA nou = 1000001. Dezactivarea CPP nu permite duplicatul (indexul m_product_value respinge). Redenumirea sa ulterior a reușit cu HTTP 200. Un nou produs id=1000003 a primit exact codul CPP inițial cu HTTP 201. Defectul privește codul intern de căutare Value, separat de M_Product_ID.',['E-SANDBOX'],'FAIL_DOVEDIT');
append(8,'În seed-ul încă în curs de aplicare a metadatelor s-au salvat M_Product și antet BOM, dar prima încercare de creare a liniei BOM a eșuat cu HTTP 500 (EVA_StocWms lipsea). Separă acest incident tranzitoriu de limitarea PK din validatorul instalat.',['E-SANDBOX']);
append(10,'În GardenWorld, M_Production_ID=1000000 a ajuns CO și a creat trei M_Transaction reale cu cantități -1,-1,+1. Posted=E și 0 Fact_Acct la observație. Nucleul producției contabilizează mișcarea stocată efectiv; simpla ambalare reversibilă nu trebuie trecută prin acest document pentru a crea stoc suplimentar.',['E-SANDBOX']);
append(18,'UI GardenWorld a salvat antetul Native Inventory 1000000; linia cu 20 scriptic și 18 numărat a fost creată prin REST cu HTTP 201. Cele două cereri CO simultane în timpul inițializării au dat HTTP 500 (tabelul de validare încă absent); antetul a rămas DR și stoc/GL nemodificate, 0 M_Transaction.',['E-SANDBOX']);
append(19,'Fereastra nativă Physical Inventory și taburile Inventory Count Line/Attributes au fost deschise pe rolul GardenWorld Admin. Dovezi UI în physical-inventory.png și inventory-saved.png.',['E-SANDBOX']);
append(21,'Testul de etichete a fost reluat cu fonturile reale DejaVu din imagine și bibliotecile încorporate ale pluginului. Suita adaptată la mediul local a obținut 467 verificări OK și 0 FAIL. Imprimarea pe hardware și ambiguitatea codurilor comerciale rămân probe separate.',['E-CROSSCHECK']);
append(3,'Aserțiunea originală nereușită la activare controla „/com/eva/ro/contab/wms/” pe o cale Windows. Cu separatori normalizați, TestRegulaLegaturaWms a trecut 217/217 pe JAR-ul neschimbat.',['E-CROSSCHECK']);
append(29,'Rezultatul efectiv al producției 1000000 este CO / Processed=Y / Posted=E / Fact_Acct=0. Pentru inventarul 1000000 într-un mediu care nu terminase instalarea, două CO eșuate păstrează DR, Processed=N, Posted=N și stoc=20.',['E-SANDBOX']);
function finding(id,title,severity,controls,fact,scope,diagnostics,remediation,regression){const f={finding_id:'A05-'+id,title,severity,status:'CONFIRMAT',confidence:'ridicată la domeniul probelor enumerate',classification:scope,observed_fact:fact,file_symbol_lines_sha:diagnostics,control_ids:controls.map(k=>'A05-C'+String(k).padStart(2,'0')),native_first_remediation:remediation,regression_test:regression,evidence_level:'SANDBOX_E2E + STATIC_SOURCE + LIVE_READ_ONLY unde este indicat',impact:title,owner:'A05 împreună cu A02/A10',A11_decision:null,false_positive_history:[],evidence_ids:['E-SANDBOX'],reproduction:regression};a.findings.push(f);for(const c of a.controls.filter(x=>f.control_ids.includes(x.control_id)))c.findings.push(f.finding_id);}
finding('F08','Codul produsului poate fi realocat după redenumirea produsului vechi','RIDICAT',[4],'201 la creare a produselor discrete CPP/CPA, 500 la duplicare după dezactivare, 200 la redenumire, apoi 201 la realocarea codului vechi unei identități noi. Dovezi independente: index unic în live și răspunsuri REST în seed.','Cerință EVA de identitate permanentă; unicitatea unui ID numeric sau UUID nu echivalează cu nereutilizarea codului Value.',[{file:'A05/sandbox-product-identity.txt',sha256:hash(p.join(e,'sandbox-product-identity.txt'))},{file:'A05/metadate.txt',sha256:hash(p.join(e,'metadate.txt')),anchor:'m_product_value'}],'Păstrează M_Product și identificatori nativi. Decide dacă Value este codul permanent. Dacă da, împiedică schimbarea valorii și reutilizarea prin orice cale PO/import. Dacă redenumirea este necesară, rezervă vechile valori într-un registru persistent. Constrângerea trebuie să reziste la concurență și revenire din arhivă.','Același cod rămâne indisponibil la dezactivare, redenumire, import, ștergere permisă și două alocări simultane. SKU/EAN pot evolua independent.');
finding('F09','ERP acceptă operații înainte ca extensia WMS să își fi instalat tabelele','RIDICAT',[8,18,29],'În seed-ul izolat, un operator autorizat a salvat antet Inventar și linia. Două CO concurente au răspuns HTTP 500; logul identifică EVA_ValidareProdusInv inexistentă. Produs și antet BOM acceptate, linie BOM respinsă din cauza lipsei EVA_StocWms. Nicio tranzacție de stoc parțială la inventar.','Pornire/upgrade pe seed GardenWorld, nu starea cabinetului CESIRO.',[src('EvaActivator',['evenimenteValidareProdus = new','evenimenteNotaSetBom = new','new Thread(this::aplica','EvaMetadata.ensureAll']),src('component/EvaNotaSetBomEvents',['SQL_FOLOSITA =','(c, v) -> DB.getSQLValueEx'])],'Aplică pachetele/dicționarul și verifică explicit tabelele, procesele, FormFactory și drepturile înainte de a permite documente sau a activa validatori dependenti. Folosește mecanismul nativ de migrații și o verificare de disponibilitate pentru WMS. Obiectivele G1 dependente de validare trebuie refuzate controlat, fără a ocoli inventarul.','Seed nativ curat, extensie instalată, două salvări în fereastra de inițializare. Verifică refuzul explicabil și după disponibilitate retestează aceleași documente, cu un singur efect.');
